snippet_css:
:root{
  --bg: #000018;
  --fg: #00FF41;
  --muted: #2FB862;
  --surface: #0B0B2E;
  --border: #C0C0C0;
  --accent: #00FFFF;
  --accent-fg: #00201F;
  --accent-grad: linear-gradient(180deg,#5CFFFF,#00D9D9);
  --radius: 0px;
  --radius-sm: 0px;
  --shadow: inset 1px 1px 0 rgba(255,255,255,.35),inset -1px -1px 0 #000,3px 3px 0 rgba(0,0,0,.55);
  --btn-shadow: inset 1px 1px 0 rgba(255,255,255,.5),inset -1px -1px 0 #000,3px 3px 0 rgba(0,0,0,.6);
  --art-bg: linear-gradient(180deg,#000036,#000018);
  --media-bg: radial-gradient(rgba(255,255,255,.2) 1px,transparent 1.5px) 0 0/22px 22px,linear-gradient(180deg,#000030,#000018);
  --cta-bg: linear-gradient(180deg,#0B0B2E,#000018);
  --input-bg: #000020;
  --ok: #00FF41;
  --warn: #FF4466;
  --win-bar: linear-gradient(90deg,#000080,#1084D0);
  --win-bar-fg: #FFFFFF;
  --chrome-fg: #0A0A0A;
  --magenta: #FF00FF;
  --yellow: #FFFF00;
  --font-display: 'VT323','Noto Sans TC',monospace;
  --font-body: 'VT323','Noto Sans TC',system-ui,sans-serif;
  --font-mono: 'VT323',ui-monospace,Menlo,monospace;
  --focus-ring: var(--accent);
}

